#version 450
layout(std140, set = 0, binding = 0) uniform NrUniforms { vec2 res; vec4 nr_unit; }; layout(set = 0, binding = 1) uniform texture2D behind_nrt; layout(set = 0, binding = 2) uniform sampler behind_nrs; layout(set = 0, binding = 3) uniform texture2D shape_nrt; layout(set = 0, binding = 4) uniform sampler shape_nrs; layout(location = 0) out vec4 nr_FragColor; vec4 nr_FragCoord;





void nr_main() {
  vec2 uv = nr_FragCoord.xy / res;
  float d = clamp(texture(sampler2D(shape_nrt, shape_nrs), uv).r / 8.0, 0.0, 1.0);
  nr_FragColor = vec4(texture(sampler2D(behind_nrt, behind_nrs), uv).rgb * (0.6 + 0.4 * d), 1.0);
}

void main() { nr_FragCoord = vec4(gl_FragCoord.x * nr_unit.x, nr_unit.z - gl_FragCoord.y * nr_unit.y, 0.0, 1.0); nr_FragColor = vec4(0.0); nr_main(); }
